"""廉藺全篇作者第二遍覆讀；不代獨立審題。"""
from author import *
assert set(SPECS)==set(range(1,232))
def options(n,changes):
 for c in SPECS[n]['choices']:
  if c['id'] in changes:c['text'],c['explanation']=changes[c['id']]
options(6,{'c':('讓太子立即接掌王位，使趙王不必再赴秦會盟','另立以三十日不返為條件，並非赴會前立即取代趙王。'),'d':('讓秦知道趙將拒絕一切往來，使秦再無議和機會','絕秦望針對扣王要脅，並非永久斷絕外交往來。')})
options(8,{'a':('由相如瞪眼喝斥正面寫出的神態與行動','保留張目叱之就仍有這層正面描寫，刪去的是對方退卻的反應。'),'b':('由秦王同意擊缻直接說明的悔改與敬服','擊缻是受逼且不懌，不足以證悔改；皆靡寫的也不是秦王。'),'c':('由相如以死相逼交代出的具體對策','頸血威脅在前句已交代，皆靡只補侍從的反應，不是新對策。')})
options(13,{'b':('僅憑、只靠','僅憑需帶所憑條件，徒見欺在此說給璧卻無所得而白受騙。')})
options(22,{'a':('交還官職的印與綬','原文请罪姿態是伏刑具，沒有交還印綬辭官。'),'d':('鞭打罪人的荊與杖','荊條見後面的廉頗請罪，斧質指行刑斧與砧，器物不同。')})
options(45,{'a':('當面許諾而必定履行','佯與詐說明只是作樣子，不能當作履約保證。'),'b':('暫不決定而請求延期','秦已假意答應給城，不是尚未表態；延期由相如再提出。'),'d':('改變主意而真誠讓步','相如判實不可得，顯示他不認為秦真正改變意圖。')})
options(46,{'a':('把十五城交割給趙的程序','九賓是接待使者禮儀，秦設禮後仍未割城。'),'c':('相如與秦王私下商議的會面','設於廷的隆重禮節不同於私下會面。'),'d':('為秦王奏樂祝壽的宴禮','奏樂祝壽見澠池，九賓在此是接賓獻璧之禮。')})
options(54,{'a':('一位品格耿直的使者','介在此計量人數，未藉此評使者品格。'),'c':('一位引介兩王的中間人','普通使者傳令即可，原句沒有介紹兩王相識的任務。'),'d':('一隊護送玉璧的使團','一介說一個人，並非一隊已在護璧的使團。')})
options(67,{'b':('立即低頭認罪','退卻不等於承認罪過，原文未有謝罪言行。'),'c':('一同舉刀進逼','叱之後退卻，不能把受震懾的反應讀成繼續進攻。')})
options(74,{'a':('相如尚未外出時','已而引出後來一次外出，非回到出門之前。')})
options(76,{'a':('比廉頗更加害怕','殊甚表程度很深，未另設廉頗害怕作比較。'),'b':('對秦王的畏懼甚深','此時門客指責的是避廉，不能換成畏秦。'),'c':('只在出門時略感不安','非常厲害與略不安程度相反，也未限定只出門才如此。')})
options(88,{'a':('廉頗憑戰功成上卿；相如起初也是同級官員','廉頗部分正確，但相如起初為舍人而非同級官員。'),'b':('廉頗已有上卿之位；相如因繆賢私授而同居上卿','繆賢只是主人及推薦者，後來授官者是趙王，非私人授同級官。'),'d':('廉頗與相如同有伐齊功；二人官位只因出身而不同','相如沒有這次伐齊功；原文也未說任官只看出身。')})
options(90,{'b':('交好友誼只看兩人私交，燕弱更須保護繆賢以答恩','燕畏強趙可能綁返，不能從燕弱推成必須保護私人友人。'),'d':('繆賢一旦離趙便不受趙王管束，燕因此再無須顧趙','逃趙不使趙的國力消失，燕仍畏趙，故不能不顧其反應。')})
options(91,{'b':('燕曾交好已足保證收留，但主動請罪可先取得更多賞賜','原文否定必收留的保證，請罪所求是免罰，並非獲賞。')})
options(95,{'a':('兩方儀節雖不同，對使者的尊重實際相同','甚倨、戲弄臣明示尊重不等，不能當作純形式差異。'),'b':('趙行禮愈隆重，便代表趙已放棄獲城的要求','隆重禮節表誠意，不取消十五城交換條件。'),'c':('秦已指圖許城，便可抵消先前所有接待失禮','相如既追究無誠亦責失禮，假指城不使先前輕慢自動正當。')})
options(98,{'b':('恐趙王不肯交璧而使秦失望，故將玉璧交從者帶回秦廷','返送方向是趙國，擔心的是秦欺己負趙，兩端均讀反。'),'c':('恐秦行禮後真的割城，故先送璧返趙以中止公平交換','相如怕秦不償城，並明提秦先交城趙再奉璧，未拒公平交換。'),'d':('恐自己失去上卿之位，故先保存私有玉璧免遭損失','當時相如尚非上卿，璧屬趙國，不能解成護私產保官。')})
options(103,{'a':('讓秦趙兩王演奏同一種樂器，統一會盟儀式','兩王樂器不同，所爭是相互為對方作樂的關係，非統一樂器。'),'b':('讓秦王代替趙王表演，從紀錄中取消趙王已鼓瑟一事','相如補對等行為，未能取消已發生的趙王鼓瑟。'),'c':('讓秦王承認趙王樂藝更高，以音樂勝負決定兩國尊卑','並未評演奏優劣或決尊卑，而是防止單方面受辱。')})
options(106,{'b':('相如立功升位→廉頗被撤去官職→揚言羞辱','廉頗未被撤職，他因相如位居己上而不服。'),'c':('廉頗索取軍權→相如拒絕交出→揚言羞辱','原文爭位次與功勞評價，沒有索還軍權。'),'d':('相如否定廉頗戰功→趙王改定功勞→揚言羞辱','輕視他人功勞者是廉頗，沒有相如先向王貶低廉功。')})
options(112,{'b':('廉頗聽聞秦已永久放棄攻趙，遂認為兩人沒有合作必要','聞之指先國後私的理由，非秦永久停戰；和好也為保存共同力量。')})
options(118,{'a':('把秦王擊缻記成已答允十五城交換的證據','演奏不等於割城承諾，兩件事件與紀錄內容不能混同。'),'c':('以文字抹去趙王鼓瑟的事實，使只有秦王作樂','趙王已鼓瑟仍是事實，相如增加相應紀錄而非抹去。'),'d':('把相如的威脅列成正式命令，使其地位高於秦王','記的是秦王為趙王击缻，未把相如立為秦王上級。')})
options(119,{'c':('席上以咸陽代十五城定下交換，後方備兵確保交割','索咸陽是回敬，沒有定下土地交換，軍備也未為交割。'),'d':('席上只憑軍隊直接威脅，辭令對結果已不再有作用','咸陽答辯本身即見辭令作用，亦字補軍備而非取消外交。')})
options(120,{'a':('看重出使次數及任官年資，貶低處事的忠誠','原文比較戰功與口舌、原出身，沒有數出使次數或責其不忠。'),'b':('看重君王對兩人的褒獎，認為自己已獲更高位次','廉頗正因位居相如下而不滿，並非已在更高位。'),'c':('看重兩人能否免受私辱，認為相如先羞辱了自己','相如未先辱廉，廉以升位本身為羞，重點仍是功與出身。')})
options(121,{'a':('內鬥只要由一人獲勝，便能以單一力量取代合作','不俱生正是相如所怕，未認一人可完全代替兩人共同作用。'),'b':('內鬥可判文武誰更有功，從而減少秦對趙的壓力','相如不以內鬥評功，反認為力量受損會削弱制秦。')})
options(158,{'a':('以為、認為','以在此引升官原因，不是省略為而作認為；後面有明確任命結果。')})
options(181,{'a':('加授相如更高的秦官','厚遇不等於授秦官，相如回趙才獲趙王任命。'),'b':('把十五城作厚禮送給相如','城未真正給趙，也非贈相如私產，厚待不能擴成割城。')})
options(185,{'a':('平聲吩咐對方退後','叱帶大聲嚴厲，平聲吩咐削弱原文張目震退的聲勢。'),'b':('追問對方為何不肯演奏','受叱者是欲刃相如的左右，非不肯擊缻的秦王；叱亦非詢問。'),'c':('向趙王轉述侍從的意圖','相如當面喝斥左右，不是在旁轉述消息。')})
options(193,{'b':('說明相如升位只因繆賢關係，外交功績不足以改變出身','後文兩次明以功任官，不能把推薦關係當唯一升遷原因。'),'c':('表明廉頗出身較高便始終應居上，使他的挑釁得到作者認可','交代心理背景不等於認可偏見，結尾廉頗仍自責請罪。'),'d':('預先說明二人官階將被取消，為後來同歸平民作準備','兩人沒有被取消官階，和好也不靠降為平民。')})
options(197,{'c':('由表面退避看到認同廉頗，理解相如承認外交不及戰功','相如解释顧國，未承認外交功勞較低；讓步不等於認同對方評價。'),'d':('由表面國家危急看到個人避險，理解相如打算辭官遠走','沒有辭官遠走安排，他保全兩人在趙的力量，非退出。')})
options(199,{'a':('三事都由同一人執行軍事任務，以戰績決定最後官位','完璧澠池主要是相如外交，將相和亦非軍事任務。'),'b':('前两事已消除全部外患，因此第三事與國家利害再無關係','秦壓力仍在，正因兩人共同制秦，內鬥才關乎國家。'),'d':('前兩事只作背景，二人位次從始至終沒有變化','相如由門客升上大夫再上卿，位次變化正是衝突環節。')})
options(200,{'a':('把相如所有想法改成作者直接斷語，使事例不再重要','所述是繆賢的經驗和評價，事例正為推薦提供依據。'),'c':('以燕王實際收留繆賢的結果，證明相如熟悉外國人情','繆賢被勸止逃燕，燕王未實際收留，結果是請罪獲赦。'),'d':('以相如要求繆賢薦官的條件，說明他用計交換職位','原文未有薦官交易，相如助其請罪不以任職為交換。')})
options(205,{'c':('秦只需完成齋戒禮，弱趙便必須無條件奉璧','條件是先割十五城，禮節不代替交城。'),'d':('趙先取得十五城後，兩國實力便變得完全相等','說服仍依秦強趙弱，並未宣稱得城後實力相等。')})
options(208,{'c':('秦王派臣捧璧前往趙國','使臣奉璧在相如回述趙王敬秦時，派者與行程方向均非此項。'),'d':('趙王被臣要求親自捧璧','趙王發出派遣，臣執行，不能改成使臣命王親送。')})
options(217,{'c':('尚在考慮，未作准許','許已是同意，不是仍懸而未決。'),'d':('命令立即執行一切預案','批准建議不等於預案已到啟動條件，許只說同意。')})
options(219,{'b':('秦王已取得璧的喜悦','此句說趙先前不願逆秦歡意，不能倒成得到璧後的高興。')})
options(220,{'c':('以國君身分主持獻璧','立作立即的時間副詞，沒有任官主持的身分轉換。')})

# 不改學習目標；在題幹補足跨篇比較所需的原句。
SPECS[229]['stem']='《廉頗藺相如列傳》「指從此以往」與《論孝》「事父母幾諫，見志不從，又敬不違，勞而不怨」中的「從」，用法有何不同？'
for s in SPECS.values():
 for c in s['choices']:
  c['explanation']=c['explanation'].replace('胆怯','膽怯').replace('为何','為何').replace('解释','解釋')
 for k in ['explanation','summary']:
  for a,b in [('没有','沒有'),('未发生','未發生'),('發生','發生'),('表现','表現'),('依据','依據'),('根據','根據'),('相如据','相如據'),('對应','對應'),('对应','對應'),('预案','預案'),('強化','強化'),('强化','強化'),('才干','才幹'),('負约','負約'),('封赏','封賞'),('表達','表達'),('表达','表達'),('分别','分別'),('单凭','單憑'),('單凭','單憑'),('发生','發生'),('没做','沒做'),('难接','難接'),('杀使','殺使'),('强调','強調'),('机械','機械'),('实际','實際'),('时代','時代'),('现代','現代'),('仍须','仍須'),('为何','為何'),('两國','兩國'),('两人','兩人'),('两种','兩種'),('两個','兩個'),('从哪','從哪'),('并非','並非'),('并無','並無'),('原文说','原文說'),('通常说','通常說'),('改装','改裝'),('胆小','膽小'),('远慮','遠慮')]:s[k]=s[k].replace(a,b)
 for c in s['choices']:
  for k in ['text','explanation']:
   for a,b in [('没有','沒有'),('请罪','請罪'),('表现在','表現在'),('分別','分別'),('两','兩'),('击','擊'),('喜悦','喜悅'),('实际','實際'),('并不','並不'),('原文说','原文說')]:c[k]=c[k].replace(a,b)
